SET DEFINE OFF
SET SQLBLANKLINES ON
SET FEEDBACK OFF

BEGIN
    FOR r IN (SELECT table_name FROM user_tables WHERE table_name IN ('ALLERGIES', 'LABREFERRALS', 'BILLING', 'MEDICALRECORDS', 'PRESCRIPTIONS', 'APPOINTMENTS', 'PATIENTS', 'NONMEDICALSTAFF', 'MEDICALSTAFF', 'DEPARTMENTS')) LOOP
        EXECUTE IMMEDIATE 'DROP TABLE "' || r.table_name || '" CASCADE CONSTRAINTS';
    END LOOP;
END;
/

CREATE TABLE departments (
    departmentid NUMBER(10) NOT NULL,
    departmentname VARCHAR2(100) NOT NULL,
    description VARCHAR2(4000),
    headofdepartment NUMBER(10),
    contactnumber VARCHAR2(15),
    email VARCHAR2(100),
    CONSTRAINT pk_departments PRIMARY KEY (departmentid)
);

CREATE TABLE medicalstaff (
    medstaffid NUMBER(10) NOT NULL,
    firstname VARCHAR2(100) NOT NULL,
    lastname VARCHAR2(100) NOT NULL,
    role VARCHAR2(50),
    departmentid NUMBER(10),
    phone VARCHAR2(15),
    email VARCHAR2(100),
    hiredate DATE,
    status VARCHAR2(20),
    CONSTRAINT pk_medicalstaff PRIMARY KEY (medstaffid),
    CONSTRAINT fk_medicalstaff_1 FOREIGN KEY (departmentid) REFERENCES departments (departmentid)
);

CREATE TABLE nonmedicalstaff (
    staffid NUMBER(10) NOT NULL,
    firstname VARCHAR2(100) NOT NULL,
    lastname VARCHAR2(100) NOT NULL,
    role VARCHAR2(50),
    departmentid NUMBER(10),
    phone VARCHAR2(15),
    email VARCHAR2(100),
    hiredate DATE,
    status VARCHAR2(20),
    CONSTRAINT pk_nonmedicalstaff PRIMARY KEY (staffid),
    CONSTRAINT fk_nonmedicalstaff_1 FOREIGN KEY (departmentid) REFERENCES departments (departmentid)
);

CREATE TABLE patients (
    patientid NUMBER(10) NOT NULL,
    firstname VARCHAR2(100) NOT NULL,
    lastname VARCHAR2(100) NOT NULL,
    gender VARCHAR2(10),
    dob DATE,
    phone VARCHAR2(15),
    email VARCHAR2(100),
    address VARCHAR2(255),
    bloodtype VARCHAR2(3),
    registrationdate DATE,
    CONSTRAINT pk_patients PRIMARY KEY (patientid)
);

CREATE TABLE appointments (
    appointmentid NUMBER(10) NOT NULL,
    patientid NUMBER(10) NOT NULL,
    medstaffid NUMBER(10) NOT NULL,
    appointmentdate DATE,
    appointmenttime VARCHAR2(8),
    visittype VARCHAR2(20),
    status VARCHAR2(20),
    notes VARCHAR2(4000),
    CONSTRAINT pk_appointments PRIMARY KEY (appointmentid),
    CONSTRAINT fk_appointments_1 FOREIGN KEY (patientid) REFERENCES patients (patientid),
    CONSTRAINT fk_appointments_2 FOREIGN KEY (medstaffid) REFERENCES medicalstaff (medstaffid)
);

CREATE TABLE prescriptions (
    prescriptionid NUMBER(10) NOT NULL,
    appointmentid NUMBER(10),
    medicationname VARCHAR2(100),
    startdate DATE,
    enddate DATE,
    dosage VARCHAR2(50),
    instructions VARCHAR2(4000),
    CONSTRAINT pk_prescriptions PRIMARY KEY (prescriptionid),
    CONSTRAINT fk_prescriptions_1 FOREIGN KEY (appointmentid) REFERENCES appointments (appointmentid)
);

CREATE TABLE medicalrecords (
    recordid NUMBER(10) NOT NULL,
    patientid NUMBER(10) NOT NULL,
    medstaffid NUMBER(10) NOT NULL,
    lastvisitdate DATE,
    diagnosis VARCHAR2(4000),
    nextvisit DATE,
    CONSTRAINT pk_medicalrecords PRIMARY KEY (recordid),
    CONSTRAINT fk_medicalrecords_1 FOREIGN KEY (patientid) REFERENCES patients (patientid),
    CONSTRAINT fk_medicalrecords_2 FOREIGN KEY (medstaffid) REFERENCES medicalstaff (medstaffid)
);

CREATE TABLE billing (
    billid NUMBER(10) NOT NULL,
    appointmentid NUMBER(10),
    amount NUMBER(10,2),
    paymentmethod VARCHAR2(20),
    status VARCHAR2(20),
    dateissued DATE,
    datepaid DATE,
    CONSTRAINT pk_billing PRIMARY KEY (billid),
    CONSTRAINT fk_billing_1 FOREIGN KEY (appointmentid) REFERENCES appointments (appointmentid)
);

CREATE TABLE labreferrals (
    labreferralid NUMBER(10) NOT NULL,
    appointmentid NUMBER(10),
    testtype VARCHAR2(100),
    testdate DATE,
    result VARCHAR2(4000),
    status VARCHAR2(20),
    CONSTRAINT pk_labreferrals PRIMARY KEY (labreferralid),
    CONSTRAINT fk_labreferrals_1 FOREIGN KEY (appointmentid) REFERENCES appointments (appointmentid)
);

CREATE TABLE allergies (
    allergyid NUMBER(10) NOT NULL,
    patientid NUMBER(10) NOT NULL,
    allergy VARCHAR2(100),
    CONSTRAINT pk_allergies PRIMARY KEY (allergyid),
    CONSTRAINT fk_allergies_1 FOREIGN KEY (patientid) REFERENCES patients (patientid)
);

